const OrgChart = () => {
  return (
    <div>
      <h1 className="text-2xl font-bold mb-6">Organigramme</h1>
      <div className="card">
        <p>L organigramme sera affiche ici.</p>
      </div>
    </div>
  );
};

export default OrgChart;
